		voice_depth[3] = float(gain[voice_depth_3_at]*32768.0);
		stereo_input = int32_t((position[stereo_input_read_at]>=0x4000)*1);
		voice_base_delay[0] = int32_t((position[voice_base_delay_0_read_at]-position[voice_base_delay_0_write_at])&0x7fff);
		voice_base_delay[1] = int32_t((position[voice_base_delay_1_read_at]-position[voice_base_delay_0_write_at])&0x7fff);
